// Package webhook delivers hub events to the URLs the owner of a workspace
// subscribes: each matching event of the workspace, and of its task forks
// unless switched off, is sent as one signed HTTP POST, in seq order and at
// least once.
//
// A subscription is created, read and changed under
// /api/v1/workspaces/:slug/webhooks. Its signing secret is generated by the
// hub, shown once and stored only sealed under the operator's key, with
// package secret's SealValue. Every change of a subscription writes its
// parley.webhook.* event in the transaction of the change.
//
// The hub composes the component in internal/hub/webhook.go: it creates the
// zero value while it composes, registers its keys, schema and routes, and
// binds it in a start hook.
package webhook

import (
	"log/slog"

	"github.com/agent-fox-dev/parley/internal/event"
	"github.com/agent-fox-dev/parley/internal/secret"
	"github.com/agent-fox-dev/parley/internal/store"
)

// Deps are what the component works with: the transactional store, the
// event log it writes its events to, the operator's keys and whether secrets
// can be stored, its clock (nil for the system clock), its log (nil discards
// it) and the loaded [webhooks] settings. Keys is a function so that the
// component reads the keys as they are when it needs them; nil is no key.
// Available nil means a current key is among Keys.
type Deps struct {
	Store     *store.Store
	Events    *event.Component
	Keys      func() secret.Keys
	Available func() bool
	Clock     event.Clock
	Logger    *slog.Logger
	Settings  Settings
}

// Component is the event webhook feature. The hub creates its zero value
// while it composes, registers its routes, and binds it in a start hook.
type Component struct {
	deps Deps
}

// Bind gives the component its dependencies, filling the defaults of the
// optional ones.
func (c *Component) Bind(d Deps) {
	if d.Clock == nil {
		d.Clock = event.SystemClock(nil)
	}
	if d.Logger == nil {
		d.Logger = slog.New(slog.DiscardHandler)
	}
	if d.Keys == nil {
		d.Keys = func() secret.Keys { return secret.Keys{} }
	}
	if d.Available == nil {
		keys := d.Keys
		d.Available = func() bool { return keys().Current != nil }
	}
	c.deps = d
}
